import{_ as s,r as n,o as d,c as r,b as t,d as e,a,e as i}from"./app-4a471c06.js";const c={},l=t("h3",{id:"交易-transactions",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#交易-transactions","aria-hidden":"true"},"#"),e(" 交易 transactions")],-1),_=t("p",null,"区块链是一个全球共享的事务数据库。这意味着每个人只要参与网络就可以读取数据库中的条目。如果你想更改数据库中的某些内容，你必须创建一个所谓的交易，该交易必须得到所有其他人的接受。交易一词意味着你想要进行的更改（假设你想同时更改两个值）要么根本没有完成，要么完全应用。此外，当你的事务被应用到数据库时，其他任何事务都无法更改它。",-1),h=t("h3",{id:"区块-blocks",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#区块-blocks","aria-hidden":"true"},"#"),e(" 区块 blocks")],-1),g=t("p",null,"需要克服的一个主要障碍是所谓的“双重支付攻击”（用比特币术语来说）：如果网络中存在两笔交易，它们都想清空一个账户，会发生什么？只有一笔交易是有效的，通常是先被接受的交易。问题是，“先”在对等网络中不是一个客观术语。",-1),u=t("p",null,"对此的抽象回答是，您不必关心。系统会为您选择一个全球接受的交易顺序，从而解决冲突。交易将被捆绑到所谓的“区块”中，然后在所有参与节点之间执行和分发。如果两笔交易相互矛盾，那么最终排名第二的交易将被拒绝，并且不会成为区块的一部分。",-1),p=t("p",null,"这些区块在时间上形成线性序列，这就是“区块链”一词的由来。区块会定期添加到链中，尽管这些间隔将来可能会发生变化。",-1),b={href:"https://ethereum.org/en/developers/docs/consensus-mechanisms/pos/attestations/",target:"_blank",rel:"noopener noreferrer"},k=i(`<blockquote><p>交易不能保证一定会被包含在下一个区块或任何特定的未来区块中，因为交易被包含在哪个区块中并不由交易的提交者决定，而是由矿工决定。</p></blockquote><h3 id="常见单位换算" tabindex="-1"><a class="header-anchor" href="#常见单位换算" aria-hidden="true">#</a> <strong>常见单位换算</strong></h3><blockquote><p>以太坊的最小单位是 <strong>Wei</strong>，1 ETH 被拆分成 <strong>10¹⁸</strong> 个 Wei，就像 <strong>1 元 = 100 分</strong> 一样。</p><p>💡 <strong>Gwei（10⁹ Wei）是 Gas 费计算的常用单位</strong>，比如</p></blockquote><div class="language-solidity line-numbers-mode" data-ext="solidity"><pre class="language-solidity"><code>gasPrice <span class="token operator">=</span> <span class="token number">50</span> gwei<span class="token punctuation">;</span>  <span class="token comment">// 50 Gwei</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><table><thead><tr><th><strong>单位</strong></th><th><strong>换算关系</strong></th><th><strong>示例</strong></th></tr></thead><tbody><tr><td><strong>Wei</strong></td><td>1 Wei = 1</td><td><code>1 wei</code></td></tr><tr><td><strong>Kwei</strong></td><td>1 Kwei = 10³ Wei</td><td><code>1000 wei</code></td></tr><tr><td><strong>Mwei</strong></td><td>1 Mwei = 10⁶ Wei</td><td><code>1_000_000 wei</code></td></tr><tr><td><strong>Gwei</strong></td><td>1 Gwei = 10⁹ Wei</td><td><code>1_000_000_000 wei</code></td></tr><tr><td><strong>Szabo</strong></td><td>1 Szabo = 10¹² Wei</td><td><code>1_000_000_000_000 wei</code></td></tr><tr><td><strong>Finney</strong></td><td>1 Finney = 10¹⁵ Wei</td><td><code>1_000_000_000_000_000 wei</code></td></tr><tr><td><strong>Ether</strong></td><td>1 Ether = 10¹⁸ Wei</td><td><code>1_000_000_000_000_000_000 wei</code></td></tr></tbody></table>`,5);function m(w,f){const o=n("ExternalLinkIcon");return d(),r("div",null,[l,_,h,g,u,p,t("p",null,[e("作为“顺序选择机制”的一部分，即所谓的"),t("a",b,[e("证明"),a(o)]),e("，可能会发生区块不时被撤销的情况，但仅限于链的“顶端”。在特定区块顶部添加的区块越多，该区块被撤销的可能性就越小。因此，您的交易可能会被撤销，甚至从区块链中删除，但您等待的时间越长，这种可能性就越小。")]),k])}const v=s(c,[["render",m],["__file","qukuailianjichuzhishi.html.vue"]]);export{v as default};
